import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-137: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short137', durationInSeconds: 31.2, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short137: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(27.5);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{text: "FABLE 5.2 IS"}, {text: "20% CHEAPER", accent: true}];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(3.1)}>
        <CoverImage src="projects/short-137/cover.png" out={secToFrame(3.1) - 10} />
        <HookTitle hold onDark kicker="CLAUDE API" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(7.6)}>
        <ToolCard name="Fable 5.2" tagline="Input per 1M tokens." chip="$8" at={secToFrame(3.1) - 2}>
          <Panel>
            <Line k="input /1M" v="$8" good />
            <Line k="output /1M" v="$40" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(10.2)}>
        <ToolCard name="Fable 5.1" tagline="The old price." chip="$10" at={secToFrame(7.6) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input /1M" v="$10" bad />
            <Line k="output /1M" v="$50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(13.1)}>
        <ToolCard name="Output drops" tagline="Per 1M tokens." chip="$40" at={secToFrame(10.2) - 2}>
          <Panel>
            <Line k="5.1" v="$50" bad />
            <Line k="5.2" v="$40" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(15.8)}>
        <ToolCard name="Cache hits" tagline="Per 1M tokens." chip="$0.20" at={secToFrame(13.1) - 2}>
          <Panel>
            <Line k="5.1" v="$0.25" bad />
            <Line k="5.2" v="$0.20" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(18.8)}>
        <ToolCard name="Fast mode" tagline="Premium speed." chip="2X" at={secToFrame(15.8) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="input /1M" v="$16" />
            <Line k="output /1M" v="$80" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(23.2)}>
        <ToolCard name="100M tokens a month" tagline="Input only." chip="-$200" at={secToFrame(18.8) - 2}>
          <Panel>
            <Line k="5.1" v="$1,000" bad />
            <Line k="5.2" v="$800" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Still on 5.1?" tagline="Overpaying." chip="+$2" at={secToFrame(23.2) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="5.1 input" v="$10" bad />
            <Line k="5.2 input" v="$8" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-137/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="CLAUDE API" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Fable 5.2: $8 in. Not $10.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short137;
